+}
+
+fn log_with_level(level: &str, target: &str, message: &str) {
+    let timestamp = OffsetDateTime::now_utc()
+        .format(TIMESTAMP_FORMAT)
+        .unwrap_or_else(|_| "1970-01-01T00:00:00.000Z".to_owned());
+    eprintln!("{timestamp} {:<5} [{target}] {message}", level);
+}
+
+fn read_lsp_message(reader: &mut impl BufRead) -> Option<Value> {
+    let mut content_length = None;
+    let mut line = String::new();
+
+    loop {
+        line.clear();
+        let bytes = reader.read_line(&mut line).ok()?;
+        if bytes == 0 {
+            return None;
+        }
+
+        let trimmed = line.trim_end_matches(['\r', '\n']);
+        if trimmed.is_empty() {
+            break;
+        }
+
+        if let Some((name, value)) = trimmed.split_once(':') {
+            if name.eq_ignore_ascii_case("content-length") {
+                content_length = value.trim().parse::<usize>().ok();
+            }
+        }
+    }
+
+    let length = content_length?;
+    let mut body = vec![0; length];
+    reader.read_exact(&mut body).ok()?;
+    serde_json::from_slice(&body).ok()
+}
+
+fn write_lsp_message<T: Serialize>(writer: &mut impl Write, value: &T) -> io::Result<()> {
+    let body = serde_json::to_vec(value).map_err(io::Error::other)?;
+    write!(writer, "Content-Length: {}\r\n\r\n", body.len())?;
+    writer.write_all(&body)?;
+    writer.flush()
+}
+
+fn root_uri_path(params: Option<&Value>) -> Option<PathBuf> {
+    let params = params?.as_object()?;
+
+    if let Some(root_uri) = params.get("rootUri").and_then(Value::as_str) {
+        return file_uri_to_path(root_uri);
+    }
+
+    params
+        .get("rootPath")
+        .and_then(Value::as_str)
+        .map(PathBuf::from)
+}
+
+fn file_uri_to_path(uri: &str) -> Option<PathBuf> {
+    uri.strip_prefix("file://").map(PathBuf::from)
+}
