+fn run_check(path: Option<PathBuf>, _all_targets: bool, _all_features: bool) -> i32 {
+    let sysroot = default_sysroot_path();
+    if !sysroot.exists() {
+        log_info("rustowl::toolchain", "sysroot not found; start setup toolchain");
+        if simulate_install_failure().is_err() {
+            log_error("rustowl::toolchain", "()");
+            return 1;
+        }
+    }
+
+    let selection = select_tools(&sysroot);
+    log_initial_tool_selection(&selection);
+
+    let analysis_target = resolve_target(path);
+    if !is_valid_analysis_file(&analysis_target) {
+        log_warn(
+            "rustowl::lsp::analyze",
+            &format!("Invalid analysis target: {}", analysis_target.display()),
+        );
+        log_error("rustowl", "Analyze failed");
+        return 1;
+    }
+
+    log_info("rustowl::lsp::backend", "wait 100ms for rust-analyzer");
+    thread::sleep(Duration::from_millis(100));
+    log_info("rustowl::lsp::backend", "stop running analysis processes");
+    log_info("rustowl::lsp::backend", "start analysis");
+    log_info("rustowl::lsp::backend", "analyze 1 packages...");
+
+    if selection.rustowlc_in_sysroot {
+        log_info("rustowl::toolchain", "rustowlc is selected in sysroot/bin");
+    } else {
+        log_warn("rustowl::toolchain", "rustowlc not found; fallback");
+    }
+
+    log_info(
+        "rustowl::lsp::analyze",
+        &format!("start analyzing {}", analysis_target.display()),
+    );
+    eprintln!();
+    eprintln!("thread 'tokio-runtime-worker' panicked at {PANIC_LOCATION}:");
+    eprintln!(
+        "called `Result::unwrap()` on an `Err` value: Os {{ code: 2, kind: NotFound, message: \"No such file or directory\" }}"
+    );
+    eprintln!("note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace");
+    log_error("rustowl", "Analyze failed");
+    1
+}
