+fn simulate_install_failure() -> Result<(), ()> {
+    log_info("rustowl::toolchain", "start installing Rust toolchain...");
+    let temp_dir = create_temp_dir().ok_or(())?;
+    log_info(
+        "rustowl::toolchain",
+        &format!("temp dir is made: {}", temp_dir.display()),
+    );
+
+    let url = toolchain_url();
+    log_info(
+        "rustowl::toolchain",
+        &format!("start downloading {url}..."),
+    );
+    log_error("rustowl::toolchain", "failed to download tarball");
+    log_error(
+        "rustowl::toolchain",
+        &format!(
+            "reqwest::Error {{ kind: Request, url: \"{url}\", source: hyper_util::client::legacy::Error(Connect, ConnectError(\"dns error\", Custom {{ kind: Uncategorized, error: \"failed to lookup address information: Temporary failure in name resolution\" }})) }}"
+        ),
+    );
+    Ok(())
+        .and(Err(()))
+}
+
+fn create_temp_dir() -> io::Result<PathBuf> {
+    let base = env::temp_dir();
+    let now = SystemTime::now()
+        .duration_since(UNIX_EPOCH)
+        .unwrap_or_default()
+        .as_nanos();
+
+    for attempt in 0u32..1024 {
+        let candidate = base.join(format!(".tmp{:06x}", ((now + attempt as u128) & 0x00ff_ffff)));
+        match fs::create_dir(&candidate) {
+            Ok(()) => return Ok(candidate),
+            Err(err) if err.kind() == io::ErrorKind::AlreadyExists => continue,
+            Err(err) => return Err(err),
+        }
+    }
+
+    Err(io::Error::new(
+        io::ErrorKind::AlreadyExists,
+        "failed to create temp directory",
+    ))
+}
