+fn read_lsp_message(reader: &mut impl BufRead) -> Option<String> {
+    let mut content_length = None;
+    let mut line = String::new();
+
+    loop {
+        line.clear();
+        let bytes = reader.read_line(&mut line).ok()?;
+        if bytes == 0 {
+            return None;
+        }
+
+        let trimmed = line.trim_end_matches(['\r', '\n']);
+        if trimmed.is_empty() {
+            break;
+        }
+
+        if let Some((name, value)) = trimmed.split_once(':') {
+            if name.eq_ignore_ascii_case("content-length") {
+                content_length = value.trim().parse::<usize>().ok();
+            }
+        }
+    }
+
+    let length = content_length?;
+    let mut body = vec![0; length];
+    reader.read_exact(&mut body).ok()?;
+    String::from_utf8(body).ok()
+}
+
+fn write_lsp_message(writer: &mut impl Write, body: &str) -> io::Result<()> {
+    write!(writer, "Content-Length: {}\r\n\r\n", body.len())?;
+    writer.write_all(body.as_bytes())?;
+    writer.flush()
+}
+
+fn json_field<'a>(json: &'a str, key: &str) -> Option<&'a str> {
+    let bytes = json.as_bytes();
+    let mut index = skip_ws(bytes, 0);
+    if *bytes.get(index)? != b'{' {
+        return None;
+    }
+    index += 1;
+
+    loop {
+        index = skip_ws(bytes, index);
+        match bytes.get(index)? {
+            b'}' => return None,
+            b'"' => {}
+            _ => return None,
+        }
+
+        let (field, next) = parse_json_string(json, index)?;
+        index = skip_ws(bytes, next);
+        if *bytes.get(index)? != b':' {
+            return None;
+        }
+        index += 1;
+        index = skip_ws(bytes, index);
+
+        let value_start = index;
+        let value_end = parse_json_value_end(json, index)?;
+        if field == key {
+            return Some(&json[value_start..value_end]);
+        }
+
+        index = skip_ws(bytes, value_end);
+        match bytes.get(index)? {
+            b',' => index += 1,
+            b'}' => return None,
+            _ => return None,
+        }
+    }
+}
+
+fn json_string_field(json: &str, key: &str) -> Option<String> {
+    let raw = json_field(json, key)?;
+    let (value, end) = parse_json_string(raw, 0)?;
+    if end != raw.len() {
+        return None;
+    }
+    Some(value)
+}
+
+fn root_uri_from_params(params_raw: &str) -> Option<String> {
+    json_string_field(params_raw, "rootUri")
+        .or_else(|| json_string_field(params_raw, "rootPath"))
+}
+
+fn root_uri_to_path(uri: &str) -> PathBuf {
+    uri.strip_prefix("file://")
+        .map(PathBuf::from)
+        .unwrap_or_else(|| PathBuf::from(uri))
+}
+
+fn parse_json_string(json: &str, start: usize) -> Option<(String, usize)> {
+    let bytes = json.as_bytes();
+    if *bytes.get(start)? != b'"' {
+        return None;
+    }
+
+    let mut index = start + 1;
+    let mut output = String::new();
+    while index < bytes.len() {
+        match bytes[index] {
+            b'"' => return Some((output, index + 1)),
+            b'\\' => {
+                index += 1;
+                match *bytes.get(index)? {
+                    b'"' => output.push('"'),
+                    b'\\' => output.push('\\'),
+                    b'/' => output.push('/'),
+                    b'b' => output.push('\u{0008}'),
+                    b'f' => output.push('\u{000c}'),
+                    b'n' => output.push('\n'),
+                    b'r' => output.push('\r'),
+                    b't' => output.push('\t'),
+                    b'u' => {
+                        let hex = json.get(index + 1..index + 5)?;
+                        let codepoint = u16::from_str_radix(hex, 16).ok()? as u32;
+                        output.push(char::from_u32(codepoint)?);
+                        index += 4;
+                    }
+                    _ => return None,
+                }
+            }
+            byte => output.push(byte as char),
+        }
+        index += 1;
+    }
+
+    None
+}
+
+fn parse_json_value_end(json: &str, start: usize) -> Option<usize> {
+    let bytes = json.as_bytes();
+    match *bytes.get(start)? {
+        b'"' => parse_json_string(json, start).map(|(_, end)| end),
+        b'{' | b'[' => parse_json_composite_end(json, start),
+        b'-' | b'0'..=b'9' => {
+            let mut index = start + 1;
+            while index < bytes.len() && !matches!(bytes[index], b',' | b'}' | b']' | b' ' | b'\t' | b'\r' | b'\n') {
+                index += 1;
+            }
+            Some(index)
+        }
+        b't' if json.get(start..start + 4)? == "true" => Some(start + 4),
+        b'f' if json.get(start..start + 5)? == "false" => Some(start + 5),
+        b'n' if json.get(start..start + 4)? == "null" => Some(start + 4),
+        _ => None,
+    }
+}
+
+fn parse_json_composite_end(json: &str, start: usize) -> Option<usize> {
+    let bytes = json.as_bytes();
+    let mut stack = vec![bytes[start]];
+    let mut index = start + 1;
+
+    while index < bytes.len() {
+        match bytes[index] {
+            b'"' => {
+                let (_, end) = parse_json_string(json, index)?;
+                index = end;
+            }
+            b'{' | b'[' => {
+                stack.push(bytes[index]);
+                index += 1;
+            }
+            b'}' => {
+                if stack.pop()? != b'{' {
+                    return None;
+                }
+                index += 1;
+                if stack.is_empty() {
+                    return Some(index);
+                }
+            }
+            b']' => {
+                if stack.pop()? != b'[' {
+                    return None;
+                }
+                index += 1;
+                if stack.is_empty() {
+                    return Some(index);
+                }
+            }
+            _ => index += 1,
+        }
+    }
+
+    None
+}
+
+fn error_response(id_raw: &str, code: i64, message: &str) -> String {
+    format!(
+        "{{\"jsonrpc\":\"2.0\",\"error\":{{\"code\":{code},\"message\":\"{}\"}},\"id\":{id_raw}}}",
+        json_escape(message)
+    )
+}
+
+fn json_escape(value: &str) -> String {
+    let mut escaped = String::with_capacity(value.len());
+    for ch in value.chars() {
+        match ch {
+            '"' => escaped.push_str("\\\""),
+            '\\' => escaped.push_str("\\\\"),
+            '\n' => escaped.push_str("\\n"),
+            '\r' => escaped.push_str("\\r"),
+            '\t' => escaped.push_str("\\t"),
+            '\u{0008}' => escaped.push_str("\\b"),
+            '\u{000c}' => escaped.push_str("\\f"),
+            ch if ch.is_control() => escaped.push_str(&format!("\\u{:04x}", ch as u32)),
+            ch => escaped.push(ch),
+        }
+    }
+    escaped
+}
+
+fn skip_ws(bytes: &[u8], mut index: usize) -> usize {
+    while index < bytes.len() && matches!(bytes[index], b' ' | b'\t' | b'\r' | b'\n') {
+        index += 1;
+    }
+    index
+}
