use std::env;
use std::ffi::OsString;
use std::fs;
use std::io::{self, BufRead, BufReader, BufWriter, Read, Write};
use std::path::{Path, PathBuf};
use std::process;
use std::thread;
use std::time::{Duration, SystemTime, UNIX_EPOCH};

const APP_NAME: &str = "RustOwl";
const VERSION: &str = env!("CARGO_PKG_VERSION");
const TOOLCHAIN_DATE: &str = "2025-06-20";
const HOST_TRIPLE: &str = "x86_64-unknown-linux-gnu";
const PANIC_LOCATION: &str = "/workspace/src/lsp/analyze.rs:222:41";

const BASH_COMPLETIONS: &str = include_str!("../completions/bash");
const ELVISH_COMPLETIONS: &str = include_str!("../completions/elvish");
const FISH_COMPLETIONS: &str = include_str!("../completions/fish");
const NUSHELL_COMPLETIONS: &str = include_str!("../completions/nushell");
const POWERSHELL_COMPLETIONS: &str = include_str!("../completions/powershell");
const ZSH_COMPLETIONS: &str = include_str!("../completions/zsh");

enum Action {
    Banner,
    PrintStdout(String),
    PrintStderr(String, i32),
    Check {
        path: Option<PathBuf>,
        all_targets: bool,
        all_features: bool,
    },
    Clean,
    ToolchainNoop,
    ToolchainInstall,
    ToolchainUninstall,
    Stdio,
}

struct ParseError {
    code: i32,
    stderr: String,
}

struct RootOptions {
    version: bool,
    quiet: u8,
    stdio: bool,
}

struct CheckArgs {
    path: Option<PathBuf>,
    all_targets: bool,
    all_features: bool,
}

#[derive(Clone, Copy)]
enum Shell {
    Bash,
    Elvish,
    Fish,
    Powershell,
    Zsh,
    Nushell,
}

struct ToolSelection {
    cargo_in_sysroot: bool,
    rustowlc_in_sysroot: bool,
}

fn main() {
    let args: Vec<OsString> = env::args_os().collect();
    let bin = program_name(args.first());

    let action = match parse_root(&args[1..], &bin) {
        Ok(action) => action,
        Err(err) => {
            eprint!("{}", err.stderr);
            process::exit(err.code);
        }
    };

    let code = run_action(action);
    process::exit(code);
}

fn run_action(action: Action) -> i32 {
    match action {
        Action::Banner => {
            print_banner();
            0
        }
        Action::PrintStdout(text) => {
            print!("{text}");
            0
        }
        Action::PrintStderr(text, code) => {
            eprint!("{text}");
            code
        }
        Action::Check {
            path,
            all_targets,
            all_features,
        } => run_check(path, all_targets, all_features),
        Action::Clean => run_clean(),
        Action::ToolchainNoop => 0,
        Action::ToolchainInstall => run_toolchain_install(),
        Action::ToolchainUninstall => run_toolchain_uninstall(),
        Action::Stdio => run_stdio(),
    }
}

fn parse_root(args: &[OsString], bin: &str) -> Result<Action, ParseError> {
    let mut options = RootOptions {
        version: false,
        quiet: 0,
        stdio: false,
    };
    let mut index = 0usize;

    while index < args.len() {
        let arg = arg_string(&args[index]);
        match arg.as_str() {
            "--help" | "-h" => return Ok(Action::PrintStdout(top_help(bin))),
            "--version" | "-V" => {
                options.version = true;
                index += 1;
            }
            "--stdio" => {
                options.stdio = true;
                index += 1;
            }
            "--quiet" => {
                options.quiet = options.quiet.saturating_add(1);
                index += 1;
            }
            value if is_q_short_flag(value) => {
                options.quiet = options.quiet.saturating_add((value.len() - 1) as u8);
                index += 1;
            }
            "check" => {
                let command = parse_check(&args[index + 1..], bin)?;
                return Ok(Action::Check {
                    path: command.path,
                    all_targets: command.all_targets,
                    all_features: command.all_features,
                });
            }
            "clean" => {
                parse_zero_arg_command(&args[index + 1..], clean_help(bin), &format!("{bin} clean"))?;
                return Ok(Action::Clean);
            }
            "toolchain" => return parse_toolchain(&args[index + 1..], bin),
            "completions" => return parse_completions(&args[index + 1..], bin),
            "help" => return parse_help(&args[index + 1..], bin),
            value if value.starts_with('-') => {
                return Err(unexpected_argument(
                    value,
                    &format!("{bin} [OPTIONS] [COMMAND]"),
                    false,
                ));
            }
            value => return Err(unrecognized_subcommand(value, bin)),
        }
    }

    if options.version {
        let text = if options.quiet > 0 {
            format!("v{VERSION}\n")
        } else {
            format!("{APP_NAME} v{VERSION}\n")
        };
        return Ok(Action::PrintStdout(text));
    }

    if options.stdio {
        return Ok(Action::Stdio);
    }

    Ok(Action::Banner)
}

fn parse_help(args: &[OsString], bin: &str) -> Result<Action, ParseError> {
    if args.is_empty() {
        return Ok(Action::PrintStdout(top_help(bin)));
    }

    let first = arg_string(&args[0]);
    match first.as_str() {
        "check" => Ok(Action::PrintStdout(check_help(bin))),
        "clean" => Ok(Action::PrintStdout(clean_help(bin))),
        "toolchain" => {
            if args.len() == 1 {
                Ok(Action::PrintStdout(toolchain_help(bin)))
            } else {
                let second = arg_string(&args[1]);
                match second.as_str() {
                    "install" => Ok(Action::PrintStdout(toolchain_install_help(bin))),
                    "uninstall" => Ok(Action::PrintStdout(toolchain_uninstall_help(bin))),
                    value => Err(unrecognized_subcommand(value, &format!("{bin} toolchain"))),
                }
            }
        }
        "completions" => Ok(Action::PrintStdout(completions_help(bin))),
        value => Err(unrecognized_subcommand(value, bin)),
    }
}

fn parse_zero_arg_command(args: &[OsString], help: String, usage: &str) -> Result<(), ParseError> {
    for arg in args {
        let value = arg_string(arg);
        if value == "--help" || value == "-h" {
            return Err(ParseError {
                code: 0,
                stderr: help,
            });
        }
    }

    if let Some(first) = args.first() {
        return Err(unexpected_argument(
            &arg_string(first),
            usage,
            false,
        ));
    }

    Ok(())
}

fn parse_check(args: &[OsString], bin: &str) -> Result<CheckArgs, ParseError> {
    if args.iter().any(|arg| matches!(arg_string(arg).as_str(), "--help" | "-h")) {
        return Ok(CheckArgs {
            path: None,
            all_targets: false,
            all_features: false,
        })
        .map(|_| unreachable!());
    }

    let mut all_targets = false;
    let mut all_features = false;
    let mut path: Option<PathBuf> = None;

    for arg in args {
        let value = arg_string(arg);
        match value.as_str() {
            "--all-targets" => all_targets = true,
            "--all-features" => all_features = true,
            "--help" | "-h" => {}
            value if value.starts_with('-') => {
                let usage = if path.is_some() {
                    format!("{bin} check <path>")
                } else {
                    format!("{bin} check [OPTIONS] [path]")
                };
                return Err(unexpected_argument(value, &usage, true));
            }
            _ if path.is_none() => path = Some(PathBuf::from(arg)),
            _ => {
                let usage = format!("{bin} check <path>");
                return Err(unexpected_argument(&value, &usage, false));
            }
        }
    }

    if args.iter().any(|arg| matches!(arg_string(arg).as_str(), "--help" | "-h")) {
        return Err(ParseError {
            code: 0,
            stderr: check_help(bin),
        });
    }

    Ok(CheckArgs {
        path,
        all_targets,
        all_features,
    })
}

fn parse_toolchain(args: &[OsString], bin: &str) -> Result<Action, ParseError> {
    if args.is_empty() {
        return Ok(Action::ToolchainNoop);
    }

    let first = arg_string(&args[0]);
    match first.as_str() {
        "--help" | "-h" | "help" => {
            if args.len() == 1 {
                Ok(Action::PrintStdout(toolchain_help(bin)))
            } else {
                let second = arg_string(&args[1]);
                match second.as_str() {
                    "install" => Ok(Action::PrintStdout(toolchain_install_help(bin))),
                    "uninstall" => Ok(Action::PrintStdout(toolchain_uninstall_help(bin))),
                    value => Err(unrecognized_subcommand(value, &format!("{bin} toolchain"))),
                }
            }
        }
        "install" => parse_toolchain_install(&args[1..], bin),
        "uninstall" => parse_toolchain_uninstall(&args[1..], bin),
        value if value.starts_with('-') => {
            Err(unexpected_argument(value, &format!("{bin} toolchain [COMMAND]"), false))
        }
        value => Err(unrecognized_subcommand(value, &format!("{bin} toolchain"))),
    }
}

fn parse_toolchain_install(args: &[OsString], bin: &str) -> Result<Action, ParseError> {
    if args.iter().any(|arg| matches!(arg_string(arg).as_str(), "--help" | "-h")) {
        return Ok(Action::PrintStdout(toolchain_install_help(bin)));
    }

    let mut expect_path_value = false;
    for arg in args {
        let value = arg_string(arg);
        if expect_path_value {
            expect_path_value = false;
            continue;
        }

        match value.as_str() {
            "--path" => expect_path_value = true,
            "--skip-rustowl-toolchain" => {}
            value if value.starts_with('-') => {
                return Err(unexpected_argument(
                    value,
                    &format!("{bin} toolchain install [OPTIONS]"),
                    false,
                ));
            }
            _ => {
                return Err(unexpected_argument(
                    &value,
                    &format!("{bin} toolchain install [OPTIONS]"),
                    false,
                ));
            }
        }
    }

    Ok(Action::ToolchainInstall)
}

fn parse_toolchain_uninstall(args: &[OsString], bin: &str) -> Result<Action, ParseError> {
    if args.iter().any(|arg| matches!(arg_string(arg).as_str(), "--help" | "-h")) {
        return Ok(Action::PrintStdout(toolchain_uninstall_help(bin)));
    }

    if let Some(first) = args.first() {
        return Err(unexpected_argument(
            &arg_string(first),
            &format!("{bin} toolchain uninstall"),
            false,
        ));
    }

    Ok(Action::ToolchainUninstall)
}

fn parse_completions(args: &[OsString], bin: &str) -> Result<Action, ParseError> {
    if args.iter().any(|arg| matches!(arg_string(arg).as_str(), "--help" | "-h")) {
        return Ok(Action::PrintStdout(completions_help(bin)));
    }

    if args.is_empty() {
        return Err(ParseError {
            code: 2,
            stderr: format!(
                "error: the following required arguments were not provided:\n  <SHELL>\n\nUsage: {bin} completions <SHELL>\n\nFor more information, try '--help'.\n"
            ),
        });
    }

    if args.len() > 1 {
        let second = arg_string(&args[1]);
        return Err(unexpected_argument(
            &second,
            &format!("{bin} completions <SHELL>"),
            true,
        ));
    }

    let shell = match arg_string(&args[0]).as_str() {
        "bash" => Shell::Bash,
        "elvish" => Shell::Elvish,
        "fish" => Shell::Fish,
        "powershell" => Shell::Powershell,
        "zsh" => Shell::Zsh,
        "nushell" => Shell::Nushell,
        other if other.starts_with('-') => {
            return Err(unexpected_argument(
                other,
                &format!("{bin} completions <SHELL>"),
                true,
            ));
        }
        other => return Err(invalid_shell(other)),
    };

    let output = match shell {
        Shell::Bash => BASH_COMPLETIONS,
        Shell::Elvish => ELVISH_COMPLETIONS,
        Shell::Fish => FISH_COMPLETIONS,
        Shell::Powershell => POWERSHELL_COMPLETIONS,
        Shell::Zsh => ZSH_COMPLETIONS,
        Shell::Nushell => NUSHELL_COMPLETIONS,
    };

    Ok(Action::PrintStdout(output.to_owned()))
}

fn run_toolchain_install() -> i32 {
    if simulate_install_failure().is_err() {
        return 1;
    }
    0
}

fn run_toolchain_uninstall() -> i32 {
    let sysroot = default_sysroot_path();
    log_info("rustowl::toolchain", &format!("remove sysroot: {}", sysroot.display()));

    if let Ok(metadata) = fs::symlink_metadata(&sysroot) {
        let _ = if metadata.file_type().is_symlink() || metadata.is_file() {
            fs::remove_file(&sysroot)
        } else {
            fs::remove_dir_all(&sysroot)
        };
    }

    0
}

fn run_clean() -> i32 {
    if let Some(workspace_root) = find_workspace_root(&current_dir_lossy()) {
        let owl_target = workspace_root.join("target").join("owl");
        if let Ok(metadata) = fs::symlink_metadata(&owl_target) {
            let _ = if metadata.file_type().is_symlink() || metadata.is_file() {
                fs::remove_file(owl_target)
            } else {
                fs::remove_dir_all(owl_target)
            };
        }
    }

    0
}

fn run_check(path: Option<PathBuf>, _all_targets: bool, _all_features: bool) -> i32 {
    let sysroot = default_sysroot_path();
    if !sysroot.exists() {
        log_info("rustowl::toolchain", "sysroot not found; start setup toolchain");
        if simulate_install_failure().is_err() {
            log_error("rustowl::toolchain", "()");
            return 1;
        }
    }

    let selection = select_tools(&sysroot);
    log_initial_tool_selection(&selection);

    let analysis_target = resolve_target(path);
    if !is_valid_analysis_file(&analysis_target) {
        log_warn(
            "rustowl::lsp::analyze",
            &format!("Invalid analysis target: {}", analysis_target.display()),
        );
        log_error("rustowl", "Analyze failed");
        return 1;
    }

    log_info("rustowl::lsp::backend", "wait 100ms for rust-analyzer");
    thread::sleep(Duration::from_millis(100));
    log_info("rustowl::lsp::backend", "stop running analysis processes");
    log_info("rustowl::lsp::backend", "start analysis");
    log_info("rustowl::lsp::backend", "analyze 1 packages...");

    if selection.rustowlc_in_sysroot {
        log_info("rustowl::toolchain", "rustowlc is selected in sysroot/bin");
    } else {
        log_warn("rustowl::toolchain", "rustowlc not found; fallback");
    }

    log_info(
        "rustowl::lsp::analyze",
        &format!("start analyzing {}", analysis_target.display()),
    );
    eprintln!();
    eprintln!("thread 'tokio-runtime-worker' panicked at {PANIC_LOCATION}:");
    eprintln!(
        "called `Result::unwrap()` on an `Err` value: Os {{ code: 2, kind: NotFound, message: \"No such file or directory\" }}"
    );
    eprintln!("note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace");
    log_error("rustowl", "Analyze failed");
    1
}

fn run_stdio() -> i32 {
    print_banner();

    let stdin = io::stdin();
    let stdout = io::stdout();
    let mut reader = BufReader::new(stdin.lock());
    let mut writer = BufWriter::new(stdout.lock());
    let mut initialized = false;

    loop {
        let Some(body) = read_lsp_message(&mut reader) else {
            break;
        };

        let method = json_string_field(&body, "method");
        let id = json_field(&body, "id");
        let params = json_field(&body, "params");

        match (method.as_deref(), id) {
            (Some("initialize"), Some(id_raw)) => {
                initialized = true;
                let response = format!(
                    "{{\"jsonrpc\":\"2.0\",\"result\":{{\"capabilities\":{{\"textDocumentSync\":{{\"change\":2,\"openClose\":true,\"save\":true}},\"workspace\":{{\"workspaceFolders\":{{\"changeNotifications\":true,\"supported\":true}}}}}}}},\"id\":{id_raw}}}"
                );
                if write_lsp_message(&mut writer, &response).is_err() {
                    break;
                }

                if let Some(root_uri) = params.and_then(root_uri_from_params) {
                    let sysroot = default_sysroot_path();
                    if sysroot.exists() {
                        let path = root_uri_to_path(&root_uri);
                        if !is_valid_analysis_file(&path) {
                            let selection = select_tools(&sysroot);
                            log_initial_tool_selection(&selection);
                            log_warn(
                                "rustowl::lsp::analyze",
                                &format!("Invalid analysis target: {}", path.display()),
                            );
                        }
                    }
                }
            }
            (Some("shutdown"), Some(id_raw)) if !initialized => {
                let response = error_response(id_raw, -32002, "Server not initialized");
                if write_lsp_message(&mut writer, &response).is_err() {
                    break;
                }
            }
            (Some("shutdown"), Some(id_raw)) => {
                if let Some(params_raw) = params {
                    let response = error_response(
                        id_raw,
                        -32602,
                        &format!("Unexpected params: {}", json_escape(params_raw)),
                    );
                    if write_lsp_message(&mut writer, &response).is_err() {
                        break;
                    }
                } else {
                    let response =
                        format!("{{\"jsonrpc\":\"2.0\",\"result\":null,\"id\":{id_raw}}}");
                    if write_lsp_message(&mut writer, &response).is_err() {
                        break;
                    }
                }
            }
            (Some("exit"), None) => break,
            (Some(_), Some(id_raw)) if !initialized => {
                let response = error_response(id_raw, -32002, "Server not initialized");
                if write_lsp_message(&mut writer, &response).is_err() {
                    break;
                }
            }
            (Some(_), Some(id_raw)) => {
                let response = error_response(id_raw, -32601, "Method not found");
                if write_lsp_message(&mut writer, &response).is_err() {
                    break;
                }
            }
            _ => {}
        }
    }

    0
}

fn print_banner() {
    eprintln!("{APP_NAME} v{VERSION}");
    eprintln!("This is an LSP server. You can use --help flag to show help.");
}

fn simulate_install_failure() -> Result<(), ()> {
    log_info("rustowl::toolchain", "start installing Rust toolchain...");
    let temp_dir = create_temp_dir().ok_or(())?;
    log_info(
        "rustowl::toolchain",
        &format!("temp dir is made: {}", temp_dir.display()),
    );

    let url = toolchain_url();
    log_info(
        "rustowl::toolchain",
        &format!("start downloading {url}..."),
    );
    log_error("rustowl::toolchain", "failed to download tarball");
    log_error(
        "rustowl::toolchain",
        &format!(
            "reqwest::Error {{ kind: Request, url: \"{url}\", source: hyper_util::client::legacy::Error(Connect, ConnectError(\"dns error\", Custom {{ kind: Uncategorized, error: \"failed to lookup address information: Temporary failure in name resolution\" }})) }}"
        ),
    );
    Ok(())
        .and(Err(()))
}

fn create_temp_dir() -> io::Result<PathBuf> {
    let base = env::temp_dir();
    let now = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_nanos();

    for attempt in 0u32..1024 {
        let candidate = base.join(format!(".tmp{:06x}", ((now + attempt as u128) & 0x00ff_ffff)));
        match fs::create_dir(&candidate) {
            Ok(()) => return Ok(candidate),
            Err(err) if err.kind() == io::ErrorKind::AlreadyExists => continue,
            Err(err) => return Err(err),
        }
    }

    Err(io::Error::new(
        io::ErrorKind::AlreadyExists,
        "failed to create temp directory",
    ))
}

fn select_tools(sysroot: &Path) -> ToolSelection {
    let bin_dir = sysroot.join("bin");
    ToolSelection {
        cargo_in_sysroot: bin_dir.join("cargo").exists(),
        rustowlc_in_sysroot: bin_dir.join("rustowlc").exists(),
    }
}

fn log_initial_tool_selection(selection: &ToolSelection) {
    if selection.cargo_in_sysroot {
        log_info("rustowl::toolchain", "cargo is selected in sysroot/bin");
    } else {
        log_warn("rustowl::toolchain", "cargo not found; fallback");
    }

    if selection.rustowlc_in_sysroot {
        log_info("rustowl::toolchain", "rustowlc is selected in sysroot/bin");
    } else {
        log_warn("rustowl::toolchain", "rustowlc not found; fallback");
    }
}

fn default_sysroot_path() -> PathBuf {
    home_dir()
        .join(".rustowl")
        .join("sysroot")
        .join(format!("nightly-{TOOLCHAIN_DATE}-{HOST_TRIPLE}"))
}

fn toolchain_url() -> String {
    format!(
        "https://static.rust-lang.org/dist/{TOOLCHAIN_DATE}/rustc-nightly-{HOST_TRIPLE}.tar.gz"
    )
}

fn home_dir() -> PathBuf {
    env::var_os("HOME")
        .map(PathBuf::from)
        .unwrap_or_else(|| PathBuf::from("."))
}

fn current_dir_lossy() -> PathBuf {
    env::current_dir().unwrap_or_else(|_| PathBuf::from("."))
}

fn resolve_target(path: Option<PathBuf>) -> PathBuf {
    match path {
        Some(path) if path.is_absolute() => path,
        Some(path) => current_dir_lossy().join(path),
        None => current_dir_lossy(),
    }
}

fn find_workspace_root(start: &Path) -> Option<PathBuf> {
    let mut current = start.to_path_buf();
    loop {
        if current.join("Cargo.toml").is_file() {
            return Some(current);
        }
        if !current.pop() {
            return None;
        }
    }
}

fn is_valid_analysis_file(path: &Path) -> bool {
    path.is_file() && matches!(path.extension().and_then(|value| value.to_str()), Some("rs"))
}

fn read_lsp_message(reader: &mut impl BufRead) -> Option<String> {
    let mut content_length = None;
    let mut line = String::new();

    loop {
        line.clear();
        let bytes = reader.read_line(&mut line).ok()?;
        if bytes == 0 {
            return None;
        }

        let trimmed = line.trim_end_matches(['\r', '\n']);
        if trimmed.is_empty() {
            break;
        }

        if let Some((name, value)) = trimmed.split_once(':') {
            if name.eq_ignore_ascii_case("content-length") {
                content_length = value.trim().parse::<usize>().ok();
            }
        }
    }

    let length = content_length?;
    let mut body = vec![0; length];
    reader.read_exact(&mut body).ok()?;
    String::from_utf8(body).ok()
}

fn write_lsp_message(writer: &mut impl Write, body: &str) -> io::Result<()> {
    write!(writer, "Content-Length: {}\r\n\r\n", body.len())?;
    writer.write_all(body.as_bytes())?;
    writer.flush()
}

fn json_field<'a>(json: &'a str, key: &str) -> Option<&'a str> {
    let bytes = json.as_bytes();
    let mut index = skip_ws(bytes, 0);
    if *bytes.get(index)? != b'{' {
        return None;
    }
    index += 1;

    loop {
        index = skip_ws(bytes, index);
        match bytes.get(index)? {
            b'}' => return None,
            b'"' => {}
            _ => return None,
        }

        let (field, next) = parse_json_string(json, index)?;
        index = skip_ws(bytes, next);
        if *bytes.get(index)? != b':' {
            return None;
        }
        index += 1;
        index = skip_ws(bytes, index);

        let value_start = index;
        let value_end = parse_json_value_end(json, index)?;
        if field == key {
            return Some(&json[value_start..value_end]);
        }

        index = skip_ws(bytes, value_end);
        match bytes.get(index)? {
            b',' => index += 1,
            b'}' => return None,
            _ => return None,
        }
    }
}

fn json_string_field(json: &str, key: &str) -> Option<String> {
    let raw = json_field(json, key)?;
    let (value, end) = parse_json_string(raw, 0)?;
    if end != raw.len() {
        return None;
    }
    Some(value)
}

fn root_uri_from_params(params_raw: &str) -> Option<String> {
    json_string_field(params_raw, "rootUri")
        .or_else(|| json_string_field(params_raw, "rootPath"))
}

fn root_uri_to_path(uri: &str) -> PathBuf {
    uri.strip_prefix("file://")
        .map(PathBuf::from)
        .unwrap_or_else(|| PathBuf::from(uri))
}

fn parse_json_string(json: &str, start: usize) -> Option<(String, usize)> {
    let bytes = json.as_bytes();
    if *bytes.get(start)? != b'"' {
        return None;
    }

    let mut index = start + 1;
    let mut output = String::new();
    while index < bytes.len() {
        match bytes[index] {
            b'"' => return Some((output, index + 1)),
            b'\\' => {
                index += 1;
                match *bytes.get(index)? {
                    b'"' => output.push('"'),
                    b'\\' => output.push('\\'),
                    b'/' => output.push('/'),
                    b'b' => output.push('\u{0008}'),
                    b'f' => output.push('\u{000c}'),
                    b'n' => output.push('\n'),
                    b'r' => output.push('\r'),
                    b't' => output.push('\t'),
                    b'u' => {
                        let hex = json.get(index + 1..index + 5)?;
                        let codepoint = u16::from_str_radix(hex, 16).ok()? as u32;
                        output.push(char::from_u32(codepoint)?);
                        index += 4;
                    }
                    _ => return None,
                }
            }
            byte => output.push(byte as char),
        }
        index += 1;
    }

    None
}

fn parse_json_value_end(json: &str, start: usize) -> Option<usize> {
    let bytes = json.as_bytes();
    match *bytes.get(start)? {
        b'"' => parse_json_string(json, start).map(|(_, end)| end),
        b'{' | b'[' => parse_json_composite_end(json, start),
        b'-' | b'0'..=b'9' => {
            let mut index = start + 1;
            while index < bytes.len() && !matches!(bytes[index], b',' | b'}' | b']' | b' ' | b'\t' | b'\r' | b'\n') {
                index += 1;
            }
            Some(index)
        }
        b't' if json.get(start..start + 4)? == "true" => Some(start + 4),
        b'f' if json.get(start..start + 5)? == "false" => Some(start + 5),
        b'n' if json.get(start..start + 4)? == "null" => Some(start + 4),
        _ => None,
    }
}

fn parse_json_composite_end(json: &str, start: usize) -> Option<usize> {
    let bytes = json.as_bytes();
    let mut stack = vec![bytes[start]];
    let mut index = start + 1;

    while index < bytes.len() {
        match bytes[index] {
            b'"' => {
                let (_, end) = parse_json_string(json, index)?;
                index = end;
            }
            b'{' | b'[' => {
                stack.push(bytes[index]);
                index += 1;
            }
            b'}' => {
                if stack.pop()? != b'{' {
                    return None;
                }
                index += 1;
                if stack.is_empty() {
                    return Some(index);
                }
            }
            b']' => {
                if stack.pop()? != b'[' {
                    return None;
                }
                index += 1;
                if stack.is_empty() {
                    return Some(index);
                }
            }
            _ => index += 1,
        }
    }

    None
}

fn error_response(id_raw: &str, code: i64, message: &str) -> String {
    format!(
        "{{\"jsonrpc\":\"2.0\",\"error\":{{\"code\":{code},\"message\":\"{}\"}},\"id\":{id_raw}}}",
        json_escape(message)
    )
}

fn json_escape(value: &str) -> String {
    let mut escaped = String::with_capacity(value.len());
    for ch in value.chars() {
        match ch {
            '"' => escaped.push_str("\\\""),
            '\\' => escaped.push_str("\\\\"),
            '\n' => escaped.push_str("\\n"),
            '\r' => escaped.push_str("\\r"),
            '\t' => escaped.push_str("\\t"),
            '\u{0008}' => escaped.push_str("\\b"),
            '\u{000c}' => escaped.push_str("\\f"),
            ch if ch.is_control() => escaped.push_str(&format!("\\u{:04x}", ch as u32)),
            ch => escaped.push(ch),
        }
    }
    escaped
}

fn skip_ws(bytes: &[u8], mut index: usize) -> usize {
    while index < bytes.len() && matches!(bytes[index], b' ' | b'\t' | b'\r' | b'\n') {
        index += 1;
    }
    index
}

fn log_info(target: &str, message: &str) {
    log_with_level("INFO", target, message);
}

fn log_warn(target: &str, message: &str) {
    log_with_level("WARN", target, message);
}

fn log_error(target: &str, message: &str) {
    log_with_level("ERROR", target, message);
}

fn log_with_level(level: &str, target: &str, message: &str) {
    eprintln!("{} {:<5} [{target}] {message}", format_timestamp(), level);
}

fn format_timestamp() -> String {
    let now = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default();
    let total_seconds = now.as_secs() as i64;
    let millis = now.subsec_millis();
    let days = total_seconds.div_euclid(86_400);
    let seconds_of_day = total_seconds.rem_euclid(86_400);
    let (year, month, day) = civil_from_days(days);
    let hour = seconds_of_day / 3_600;
    let minute = (seconds_of_day % 3_600) / 60;
    let second = seconds_of_day % 60;

    format!(
        "{year:04}-{month:02}-{day:02}T{hour:02}:{minute:02}:{second:02}.{millis:03}Z"
    )
}

fn civil_from_days(days: i64) -> (i64, i64, i64) {
    let z = days + 719_468;
    let era = if z >= 0 { z } else { z - 146_096 } / 146_097;
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365;
    let mut year = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let day = doy - (153 * mp + 2) / 5 + 1;
    let month = mp + if mp < 10 { 3 } else { -9 };
    if month <= 2 {
        year += 1;
    }
    (year, month, day)
}

fn arg_string(value: &OsString) -> String {
    value.to_string_lossy().into_owned()
}

fn is_q_short_flag(value: &str) -> bool {
    value.starts_with("-q") && value[1..].bytes().all(|byte| byte == b'q')
}

fn program_name(arg0: Option<&OsString>) -> String {
    arg0.and_then(|value| {
        Path::new(value)
            .file_name()
            .map(|name| name.to_string_lossy().into_owned())
    })
    .unwrap_or_else(|| "executable".to_owned())
}

fn unexpected_argument(argument: &str, usage: &str, tip: bool) -> ParseError {
    let mut stderr = format!("error: unexpected argument '{}' found\n\n", argument);
    if tip {
        stderr.push_str(&format!(
            "  tip: to pass '{}' as a value, use '-- {}'\n\n",
            argument, argument
        ));
    }
    stderr.push_str(&format!(
        "Usage: {usage}\n\nFor more information, try '--help'.\n"
    ));
    ParseError { code: 2, stderr }
}

fn unrecognized_subcommand(command: &str, usage_prefix: &str) -> ParseError {
    ParseError {
        code: 2,
        stderr: format!(
            "error: unrecognized subcommand '{}'\n\nUsage: {usage_prefix} [OPTIONS] [COMMAND]\n\nFor more information, try '--help'.\n",
            command
        ),
    }
}

fn invalid_shell(shell: &str) -> ParseError {
    ParseError {
        code: 2,
        stderr: format!(
            "error: invalid value '{}' for '<SHELL>'\n  [possible values: bash, elvish, fish, powershell, zsh, nushell]\n\nFor more information, try '--help'.\n",
            shell
        ),
    }
}

